let theShader, vert, frag;
let rec = [],
	maxS = 3 //try changing it
let nr = 12 //try changin it
let w

function preload() {
	vert = loadStrings('https://openprocessing.org/sketch/1676796/files/shader.vert');
	frag = loadStrings('https://openprocessing.org/sketch/1676796/files/shader.frag');
}

function setup() {
	w = max(windowWidth, windowHeight)
	createCanvas(w, w, WEBGL);
	pixelDensity(1)
	noStroke()
	for (let i = 0; i < nr; i++) rec[i] = new recta()
	theShader = createShader(vert.join('\n'), frag.join('\n').replace('%%n_val%%', nr));
}

function draw() {
	theShader.setUniform('u_resolution', [width, height]);
	theShader.setUniform('u_t', frameCount);
	let arr = new Array(4 * nr).fill(0).map((x, i) => ((i % 4 == 0) ? (rec[floor(i / 4)].x) : (i % 4 == 1) ? (rec[floor(i / 4)].y) : (i % 4 == 2) ? (rec[floor(i / 4)].wi) : (rec[floor(i / 4)].he)))
	theShader.setUniform(`u_cir`, arr)
	let crr = new Array(3 * nr).fill(0).map((x, i) => (i % 3 == 0) ? rec[(i / 3) | 0].c[0] : (i % 3 == 1) ? rec[(i / 3) | 0].c[1] : rec[(i / 3) | 0].c[2])
	theShader.setUniform(`u_cirC`, crr)
	shader(theShader)
	rect(0, 0, width, height)
	for (let r of rec) r.move()
}
class recta {
	constructor(x, y) {
		this.i = rec.length;
		this.x = w / 2
		this.y = w / 2
		let t = TAU * this.i / nr
		this.speX = maxS * sin(t)
		this.speY = maxS * cos(t)
		this.c = [360 * this.i / nr, 100, 100]
		this.wi = this.he = w / 8;
	}
	show() {
		push();
		stroke("white");
		rect(this.x, this.y, this.wi, this.he);
		pop();
	}
	move() {
		let newX = this.speX + this.x;
		let newY = this.speY + this.y;
		if (newX - this.wi / 2 < 0 || newX + this.wi / 2 > w) this.speX *= -1;
		if (newY - this.he / 2 < 0 || newY + this.he / 2 > w) this.speY *= -1;
		this.x += this.speX;
		this.y += this.speY;
	}
}
