#ifdef GL_ES
precision mediump float;
#endif
#define NC %%n_val%%
uniform vec2 u_resolution;
uniform float u_cir[NC*5];
uniform vec3 u_cirC[NC];
uniform float u_t;
float sdBox( in vec2 p, in vec2 b )
{
    vec2 d = abs(p)-b;
    return length(max(d,0.0)) + min(max(d.x,d.y),0.0);
}
float sdfRec(vec2 p,vec4 r){
  p=abs(p-r.xy);
  vec2 d=p-r.zw/2.0;
  float outside=length(max(d,0.0));
  float inside=min(max(d.x,d.y),0.0);
  return outside + inside;
}
vec3 hsv2rgb(vec3 c){
  c=vec3(c.x/360.0,c.y/100.0,c.z/100.0);
  vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
  vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
  return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}
void main() {
	vec2 st = gl_FragCoord.xy/u_resolution.xy;
	vec3 color=vec3(0.0);
  for(int i=0;i<NC;i++){
		float d=sdfRec(gl_FragCoord.xy,vec4(u_cir[4*i],u_cir[4*i+1],u_cir[4*i+2],u_cir[4*i+3]));
    d=pow(abs(d),.05);                    
		color+=(1.0-d)*hsv2rgb(u_cirC[i]);
  }
  gl_FragColor = vec4(sin(64.0*color), 1.0);
}

